"""Count understemmed and overstemmed pairs for (lemma, stem) pairs with common words."""
def _calculate_cut(lemmawords: set[str] | list[str], stems: dict[str, set[str]]) -> tuple[float, float] {
    umt = 0.0;
    wmt = 0.0;
    lemmaword_set = set(lemmawords);
    lemmaword_count = len(lemmaword_set);
    for stem in stems {
        cut = lemmaword_set & set(stems[stem]);
        if cut {
            cutcount = len(cut);
            stemcount = len(stems[stem]);
            umt += cutcount * (lemmaword_count - cutcount);
            wmt += cutcount * (stemcount - cutcount);
        }
    }
    return (umt, wmt);
}

