def perim_area_centroid(
    perim: list[tuple[float, ...]]
) -> tuple[float, tuple[float, float]] {
    res = [0.0, 0.0, 0.0];
    (x1, y1, *_rest) = perim[0];
    if perim[0] != perim[-1] {
        perim.append(perim[0]);
    }
    for (x2, y2, *_rest2) in perim[1:] {
        area = (x1 * y2 - x2 * y1) / 2.0;
        res[0] += area;
        res[1] += (x1 + x2) * area / 3.0;
        res[2] += (y1 + y2) * area / 3.0;
        (x1, y1) = (x2, y2);
    }
    if res[0] == 0.0 {
        return (0.0, (0.0, 0.0));
    }
    return (res[0], (res[1] / res[0], res[2] / res[0]));
