        memo[subproblem] = float("inf");
        return float("inf");
    }
    min_num_egg = float("inf");
    for (i, egg) in enumerate(egg_weights) {
        if target_weight - egg < 0 {
            continue;
        }
        num_egg = 1 + dp_make_weight(egg_weights, target_weight - egg, memo);
        min_num_egg = min(min_num_egg, num_egg);
    }
    memo[subproblem] = min_num_egg;
    return min_num_egg;
}

