"""Finds any listings that are listed as having different assessments."""
def find_mismatches(
    listings: list[dict[str, str]],
    assessments: dict[str, list[str]],
    accuracy: float = 0.01
) -> list[dict[str, str | list[str] | None]] {
    mismatches = [];
    for listing in listings {
        if listing["title"] in assessments {
            article_assessments = assessments[listing["title"]];
            processed_assessments = [
                c.lower()
                for c in article_assessments
                if c != ''
            ];
            if len(processed_assessments) != 0 {
                assessment_ratio = processed_assessments.count(
                    listing["assessment"].lower()
                )
                    / len(processed_assessments);
                if assessment_ratio < accuracy {
                    mismatches.append({
