) -> tuple[list[list[int]], list[int]] {
    sequence_padded = [];
    sequence_length = [];
    for seq in sequences {
        seq = list(seq);
        seq_ = seq[:max_length] + [pad_tok] * max(max_length - len(seq), 0);
        sequence_padded.append(seq_);
