"""Ensure that every string within input_list is unique."""
def uniquify_list_of_strings(input_list: list[str]) -> list[str] {
    output_list = [];
    for (i, item) in enumerate(input_list) {
        rest = input_list[:i] + input_list[i + 1:];
        if item not in rest {
            output_list.append(item);
        } else {
            output_list.append(f"{item}_{i}");
        }
    }
    return output_list;
