"""Return a flat tuple of integers to represent the indices.

Slice objects are not hashable, so we convert them.
"""
def _flatten(indices: list[int | slice]) -> tuple {
    result: list[int] = [];
    for x in indices {
        if isinstance(x, slice) {
            result.extend([x.start, x.stop, x.step]);
        } else {
            result.append(x);
        }
    }
    return tuple(result);
}

"""Gets pairs of three whose sum is 0. Returns 1 if triplets found, 0 otherwise."""
def three_sum(a: list[int], s: int) -> int {
    a.sort();
    triplets: list[tuple[int, int, int]] = [];
    for i in range(len(a) - 3) {
        l = i + 1;
        r = len(a) - 1;
        while r > l {
            if a[i] + a[r] + a[l] == s and a[r] > a[l] > a[i] {
                triplets.append((a[i], a[r], a[l]));
                l += 1;
            } elif a[i] + a[r] + a[l] < s {
                l += 1;
            } else {
                r -= 1;
            }
        }
    }
    if triplets {
        return 1;
    }
    return 0;
}

"""Extract summer from month values."""
def get_season(x: int) -> tuple[int, int, int, int] {
    (summer, fall, winter, spring) = (0, 0, 0, 0);
    if x in [5, 6, 7] {
        summer = 1;
    }
    if x in [8, 9, 10] {
        fall = 1;
    }
    if x in [11, 0, 1] {
        winter = 1;
    }
    if x in [2, 3, 4] {
        spring = 1;
    }
    return (summer, fall, winter, spring);
}

