"""Extended Euclidean algorithm: return gcd and Bezout coefficients with a*alpha + b*beta = gcd."""
def extended_euclidean_gcd(a: int, b: int) -> tuple[int, int, int] {
    (alpha, s, beta, t) = (1, 0, 0, 1);
    while b > 0 {
        (a, (q, b)) = (b, divmod(a, b));
        (alpha, s) = (s, alpha - q * s);
        (beta, t) = (t, beta - q * t);
    }
    return (a, alpha, beta);
}

