                if p[jj - 1] not in {s[ii], '.'} {
                    dp[ii + 1][jj + 1] = dp[ii + 1][jj - 1];
                } else {
                    dp[ii + 1][jj + 1] = dp[ii][jj + 1] or dp[ii + 1][jj] or dp[ii + 1][jj - 1];
                }
            }
        }
    }
    return dp[-1][-1];
