"""Binary search: find whether value belongs to a sorted array; return its index or None."""
def maf_binary(sorted_array: list[int], value: int) -> int | None {
    min_idx = 0;
    max_idx = len(sorted_array) - 1;
    while min_idx <= max_idx {
        mid = (min_idx + max_idx) // 2;
        if sorted_array[mid] > value {
            max_idx = mid - 1;
        } elif sorted_array[mid] < value {
            min_idx = mid + 1;
        } else {
            return mid;
        }
    }
    return None;
}

