"""Compute the generalized Fibonacci sequence up to a given number."""
def generalized_fibonacci_sequence_up_to(n: int, p: int) -> list[int] {
    a = [1, p];
    while True {
        latest = a[-2] + a[-1];
        if latest > n {
            break;
        }
        a.append(latest);
    }
    return a;
}

