"""Count understemmed and overstemmed pairs for (lemma, stem) pairs sharing words."""
def _calculate_cut(
    lemmawords: set[str] | list[str], stems: dict[str, set[str] | list[str]]
) -> tuple[float, float] {
    umt = 0.0;
    wmt = 0.0;
    for stem in stems {
        cut = set(lemmawords) & set(stems[stem]);
        if cut {
            cutcount = len(cut);
            stemcount = len(stems[stem]);
            umt += cutcount * (len(lemmawords) - cutcount);
            wmt += cutcount * (stemcount - cutcount);
        }
    }
    return (umt, wmt);
}

