"""Binary search: find whether element value belongs to sorted_array."""
def maf_binary(sorted_array: list[int], value: int) -> int | None {
    lo = 0;
    hi = len(sorted_array) - 1;
    while lo <= hi {
        mid = (lo + hi) // 2;
        if sorted_array[mid] > value {
            hi = mid - 1;
        } elif sorted_array[mid] < value {
            lo = mid + 1;
        } else {
            return mid;
        }
    }
    return None;
}

