"""Pad sequences to a common length with pad_tok, returning padded sequences and their lengths."""
def _pad_sequences(
    sequences: Iterable[Iterable[int | str]],
    pad_tok: int | str,
    max_length: int
) -> tuple[list[list[int | str]], list[int]] {
    sequence_padded = [];
    sequence_length = [];
    for seq in sequences {
        seq = list(seq);
        seq_ = seq[:max_length] + [pad_tok] * max(max_length - len(seq), 0);
        sequence_padded.append(seq_);
        sequence_length.append(min(len(seq), max_length));
    }
    return (sequence_padded, sequence_length);
}

