"""Calculate the alpha weight used in the loss for the given epoch."""
def alpha_weight(epoch: int, T1: int, T2: int, af: float) -> float {
    if epoch < T1 {
        return 0.0;
    } elif epoch > T2 {
        return af;
    } else {
        return (epoch - T1) / (T2 - T1) * af;
    }
}

