"""Gets pairs of three whose sum is 0.

Returns 1 if triplets found, 0 if not found.
"""
def three_sum(a: list[int], s: int) -> int {
    a.sort();
    found = False;
    for i in range(len(a) - 3) {
        l = i + 1;
        r = len(a) - 1;
        while r > l {
            if a[i] + a[r] + a[l] == s and a[r] > a[l] > a[i] {
                found = True;
                l += 1;
            } elif a[i] + a[r] + a[l] < s {
                l += 1;
            } else {
                r -= 1;
            }
        }
    }
    return 1 if found else 0;
}

