"""Recursively merge dict2 on top of dict1, returning dict2."""
def merge(dict1: dict[str, object], dict2: dict[str, object]) -> dict[str, object] {
    for (key, val) in dict1.items() {
        if isinstance(val, dict) {
            dict2_node = dict2.setdefault(key, {});
            merge(val, dict2_node);
        } elif key not in dict2 {
            dict2[key] = val;
        }
    }
    return dict2;
}

