def insert_to_table(
    db: dict[str, list[dict[str, str | int]]],
    table: str,
    q: dict[str, dict[str, str | int]] | dict[str, str | int]
) -> dict[str, list[dict[str, str | int]]] {
    if 'record_id' in q {
        def update_record(record: dict[str, str | int]) -> dict[str, str | int] {
            if record[q['record_id']['key']] == q['record_id']['value'] {
                for key in record {
                    if key in q['value'] {
                        record[key] = q['value'][key];
                    }
                }
            }
            return record;
        }
        db[table] = list(map(update_record, db[table]));
        return db;
    } else {
        db[table].append(q);
    }
    return db;
}

