"""Recursively collect field structs from a JSON script dict."""
def json_get_fields(
    struct: dict[str, object] | list[object] | tuple[object, ...],
    path: list[str | int] = []
) -> dict[str, dict[str, object]] {
    fields: dict[str, dict[str, object]] = {};
    path = path[:];
    if isinstance(struct, dict) {
        if 'field' in struct {
            fields[struct['field']['name']] = struct['field'];
        } else {
            for (key, value) in struct.items() {
                fields.update(json_get_fields(value, path + [key]));
            }
        }
    } elif isinstance(struct, list) or isinstance(struct, tuple) {
        for (index, value) in enumerate(struct) {
            fields.update(json_get_fields(value, path + [index]));
        }
    }
    if path == [] {
        return sorted(
            fields.values(), key=lambda (f: dict[str, object]) { f.get('order', 0) }
        );
    }
    return fields;
}

