def dict_list_to_bins(
    dict_list: list[dict[str, str | int | float]],
    bin_key: str,
    comparison_key: str | None = None
) -> dict[str | int | float, int | float] {
    dict_bins: dict[str | int | float, int | float] = {};
    for item in dict_list {
        bin_val = item[bin_key];
        if dict_bins.get(bin_val, None) {
            if comparison_key {
                dict_bins[bin_val] += float(item[comparison_key]);
            } else {
