"""Sort a list in ascending order. The original list is mutated and
returned. The sort is stable.

Design idea: iterate over the list. After i iterations, the first i
elements are sorted. Insert the (i+1)'th element in the appropriate
spot in the sorted sublist.

Complexity: O(n^2) time, O(1) space. Stable and in-place.
"""
def insertion_sort(lst: list[object]) -> list[object] {
    for i in range(1, len(lst)) {
        v = lst[i];
        j = i - 1;
        while j >= 0 and lst[j] > v {
            lst[j + 1] = lst[j];
            j -= 1;
        }
        lst[j + 1] = v;
    }
    return lst;
}

