def init_bugfix_changes_stats(
    stats: dict[str, dict[str, int]],
    data: dict[str, str],
    commit: str,
    changes: dict[str, str]
) -> dict[str, dict[str, int]] {
    if commit not in stats {
        stats[commit] = {};
    }
    stats[commit].update({
        'n_changes': len(changes),
        'n_effective': sum(
            1
            for status in changes.values()
            if status != 'D'
        ),
        'n_renames': sum(
            1
            for status in changes.values()
            if status == 'R'
        ),
        'n_deletions': sum(
            1
            for status in changes.values()
            if status == 'D'
        ),
        'n_additions': sum(
            1
            for status in changes.values()
            if status == 'A'
        )
    });
    return stats;
}

