"""Count CIGAR operations. cigar: Unicode."""
def count_cigar_ops(cigar: str) -> tuple[int, int, int, int] {
    b = 0;
    num_m = 0;
    num_i = 0;
    num_d = 0;
    for (i, ch) in enumerate(cigar) {
        if ch <= '9' {
            continue;
        }
        assert b < i;
        count = int(cigar[b:i]);
        op = ch;
        b = i + 1;
        if op == 'D' {
            num_d += count;
        } elif op == 'I' {
            num_i += count;
        } elif op in ('M', '=', 'X') {
            num_m += count;
        }
    }
    assert b == len(cigar);
    total_len = num_d + num_i + num_m;
    return (num_m, num_i, num_d, total_len);
}

