    for i in range(3, int(n ** 0.5) + 1, 2) {
        if sieve[i] {
            sieve[i * i::2 * i] = [False] * ((n - i * i - 1) // (2 * i) + 1);
        }
    }
    return [2]
        + [
            i
            for i in range(3, n, 2)
            if sieve[i]
        ];
}

"""Linearly interpolate between adjacent x-values to estimate y at x_desired."""
def linear_interpolate(x: list[float], y: list[float], x_desired: float) -> float {
    index = 0;
    while x[index] <= x_desired {
        index += 1;
    }
    x_left = x[index - 1];
    x_right = x[index];
    y_interp = (y[index - 1] * (x_right - x_desired) + y[index] * (x_desired - x_left))
        / (x_right - x_left);
    return y_interp;
}

