}

"""Reduce a list of dictionaries into bins keyed by bin_key, optionally summing comparison_key."""
def dict_list_to_bins(
    dict_list: list[dict[str, float]],
    bin_key: str,
    comparison_key: str | None = None
) -> dict[str, float] {
    dict_bins: dict[str, float] = {};
    for item in dict_list {
        bin_val = item[bin_key];
        if dict_bins.get(bin_val, None) {
            if comparison_key {
                dict_bins[bin_val] += float(item[comparison_key]);
            } else {
                dict_bins[bin_val] += 1;
            }
        } else {
            if comparison_key {
                dict_bins[bin_val] = float(item[comparison_key]);
            } else {
                dict_bins[bin_val] = 1;
            }
        }
    }
    return dict_bins;
}

