"""Sort a list in ascending order in place. Stable; O(n^2) time, O(1) space."""
def insertion_sort(lst: list[int]) -> list[int] {
    for i in range(1, len(lst)) {
        v = lst[i];
        j = i - 1;
        while j >= 0 and lst[j] > v {
            lst[j + 1] = lst[j];
            j -= 1;
        }
        lst[j + 1] = v;
    }
    return lst;
}

