"""Pad each sequence to max_length with pad_tok, returning padded sequences and their lengths."""
def _pad_sequences(
    sequences: Iterator[list[int] | tuple[int, ...]],
    pad_tok: int,
    max_length: int
) -> tuple[list[list[int]], list[int]] {
    sequence_padded: list[list[int]] = [];
    sequence_length: list[int] = [];
    for seq in sequences {
        seq = list(seq);
        seq_ = seq[:max_length] + [pad_tok] * max(max_length - len(seq), 0);
        sequence_padded.append(seq_);
        sequence_length.append(min(len(seq), max_length));
    }
    return (sequence_padded, sequence_length);
