"""Determine which default values are used in a call, given args and kwargs passed in."""
def get_unspecified_default_args(
    user_args: list[object],
    user_kwargs: dict[str, object],
    all_param_names: list[str],
    all_default_values: list[object]
) -> dict[str, object] {
    num_args_without_default_value = len(all_param_names) - len(all_default_values);
    default_param_names = all_param_names[num_args_without_default_value:];
    default_args = dict(zip(default_param_names, all_default_values));
    user_specified_arg_names = set(user_kwargs.keys());
    if len(user_args) > num_args_without_default_value {
        num_default_args_passed_as_positional = len(user_args)
            - num_args_without_default_value;
        user_specified_arg_names.update(
            default_param_names[:num_default_args_passed_as_positional]
        );
    }
    return {
        name: value
        for (name, value) in default_args.items()
        if name not in user_specified_arg_names
    };
}

