"""N is length of arr."""
def searchsorted(arr: list[int | float], N: int, x: int | float) -> int {
    L = 0;
    R = N - 1;
    done = False;
    m = (L + R) // 2;
    while not done {
        if arr[m] < x {
            L = m + 1;
        } elif arr[m] > x {
            R = m - 1;
        } elif arr[m] == x {
            done = True;
        }
        m = (L + R) // 2;
        if L > R {
            done = True;
        }
    }
    return L;
}

"""Selection partition."""
def partition(array: list[int], pivot: int) -> int {
    i = -1;
    j = 0;
    while j < len(array) - 1 {
        if array[j] == pivot {
            (array[-1], array[j]) = (array[j], array[-1]);
            continue;
        } elif array[j] < pivot {
            i += 1;
            (array[i], array[j]) = (array[j], array[i]);
        }
        j += 1;
    }
    (array[-1], array[i + 1]) = (array[i + 1], array[-1]);
    return i + 1;
}

"""Find number of eggs to bring back, using the smallest number of eggs."""
def dp_make_weight(
    egg_weights: tuple[int, ...],
    target_weight: int,
    memo: dict[tuple[tuple[int, ...], int], int] = {}
) -> int {
    subproblem = (egg_weights, target_weight);
    if subproblem in memo {
        return memo[subproblem];
    }
    if egg_weights == () or target_weight == 0 {
        return 0;
    }
    if egg_weights[-1] > target_weight {
        result = dp_make_weight(egg_weights[:-1], target_weight, memo);
    } else {
        this_egg = egg_weights[-1];
        num_eggs_with_this_egg = 1
            + dp_make_weight(egg_weights, target_weight - this_egg, memo);
        num_eggs_without_this_egg = dp_make_weight(egg_weights[:-1], target_weight, memo);
        if num_eggs_without_this_egg != 0 {
            result = min(num_eggs_with_this_egg, num_eggs_without_this_egg);
        } else {
            result = num_eggs_with_this_egg;
        }
        memo[subproblem] = result;
    }
    return result;
}

