"""
Given two lists or arrays x and y, linearly interpolates between adjacent
x-values to give an estimated y-value for any particular x.
"""
def linear_interpolate(x: list[float], y: list[float], x_desired: float) -> float {
    index = 0;
    while x[index] <= x_desired {
        index = index + 1;
    }
    x_left = x[index - 1];
    x_right = x[index];
    y_interp = (y[index - 1] * (x_right - x_desired) + y[index] * (x_desired - x_left)) / (x_right - x_left);
    return y_interp;
}

"""removes useless points from a path and leaves only turn-points"""
def compress_path(path: list[tuple[int, int]]) -> list[tuple[int, int]] {
    new_path = path;
    i = 0;
    while i < len(new_path) - 2 {
        (x1, y1) = new_path[i];
        (x2, y2) = new_path[i + 1];
        (x3, y3) = new_path[i + 2];
        if x1 == x2 == x3 or y1 == y2 == y3 {
            new_path.pop(i + 1);
        } else {
            i += 1;
        }
    }
    return new_path;
}

"""Implementation 2 for the divide-and-conquer algorithm. Complexity: O(log n)."""
def bisection_search2(L: list[int], e: int) -> bool {
    def helper(L: list[int], e: int, low: int, high: int) -> bool {
        if high == low {
            return L[low] == e;
        }
        mid = (low + high) // 2;
        if L[mid] == e {
            return True;
        } elif L[mid] > e {
            if low == mid {
                return False;
            }
            return helper(L, e, low, mid - 1);
        } else {
            return helper(L, e, mid + 1, high);
        }
    }
    if len(L) == 0 {
        return False;
    }
    return helper(L, e, 0, len(L) - 1);
}

