"""Computes the median of a list.
NOTE: The list must be sorted!!!"""
def median(inList: list[int]) -> int | float {
    n = len(inList);
    if n == 0 {
        return 0.0;
    }
    if n == 1 {
        return inList[0];
    }
    if n % 2 == 0 {
        return (inList[n // 2] + inList[n // 2 - 1]) / 2.0;
    }
    return inList[n // 2];
}

