"""Implementation 2 for the divide-and-conquer algorithm. Complexity: O(log n)."""
def bisection_search2(L: list[int], e: int) -> bool {
    def helper(L: list[int], e: int, low: int, high: int) -> bool {
        if high == low {
            return L[low] == e;
        }
        mid = (low + high) // 2;
        if L[mid] == e {
            return True;
        } elif L[mid] > e {
            if low == mid {
                return False;
            }
            return helper(L, e, low, mid - 1);
        } else {
            return helper(L, e, mid + 1, high);
        }
    }
    if len(L) == 0 {
        return False;
    }
    return helper(L, e, 0, len(L) - 1);
}

"""Order direction of path so that we always go the same way and can define
locations order going clock wise from posterior so that left is ~25% and
right is ~75% (top view)."""
def set_direction_of_pp(pp: list[list[float]]) -> list[list[float]] {
    pplength = len(pp);
    p25 = pp[int(0.25 * pplength)];
    p75 = pp[int(0.75 * pplength)];
    if not p25[0] > p75[0] {
        pp = [pp[-i] for i in range(1, len(pp) + 1)];
    }
    return pp;
}

"""Flatten nested dictionary.

Transforms {'a': {'b': {'c': 5}, 'd': 6}} into {'a.b.c': 5, 'a.d': 6}
"""
def flatten_dict(
    d: dict[str, object] | list[object] | str | int | float | bool,
    separator: str = '.',
    prefix: str = ''
) -> dict[str, object] {
    if isinstance(d, dict) {
        return {
            (prefix + separator + k) if prefix else k: v
            for (kk, vv) in d.items()
            for (k, v) in flatten_dict(vv, separator, kk).items()
        };
    }
    return {prefix: d};
}

