"""Given a human-readable IOPs string (e.g. 2K, 30M),
return the real number.  Will return 0 if the argument has
unexpected form.
"""
def human_to_real(iops: str) -> int {
    digits = iops[:-1];
    unit = iops[-1];
    if digits.isdigit() {
        value = int(digits);
        match unit {
            case 'M':
                value *= 1000000;
            case 'K':
                value *= 1000;
            case _:
                value = 0;
        }
    } else {
        value = 0;
    }
    return value;
