"""Recursive counter: returns 2 at the base case and accumulates calls in base_case."""
def b(n: int, k: int, base_case: list[int]) -> int {
    if k == 0 or k == n {
        print('base case!');
        base_case[0] += 1;
        return 2;
    }
    return b(n - 1, k - 1, base_case) + b(n - 1, k, base_case);
}

"""Calculate the alpha weight used in the loss for the given epoch."""
def alpha_weight(epoch: int, T1: int, T2: int, af: float) -> float {
    if epoch < T1 {
        return 0.0;
    } elif epoch > T2 {
        return af;
    } else {
        return (epoch - T1) / (T2 - T1) * af;
    }
}

