    min_rating: int | float | None = None,
    max_rating: int | float | None = None
) -> list[int] {
    ratings = [int(r) for r in ratings];
    if min_rating is None {
        min_rating = min(ratings);
    }
    if max_rating is None {
        max_rating = max(ratings);
    }
