    Add 1 before each single digit. '111' -> '31'
    """
def look_and_say(numbers: str) -> str {
    digit = "";
    result = "";
    count = 0;
    for c in numbers {
        if c == digit {
            count += 1;
        } else {
            if count {
                result += str(count) + digit;
            }
            digit = c;
            count = 1;
        }
    }
    result += str(count) + digit;
    return result;
}

