"""Return number of bytes as string with most appropriate unit."""
def human_size(num_bytes: int) -> str {
    if num_bytes == 0 {
        return '0 B';
    }
    suffixes = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'YB'];
    value = float(num_bytes);
    i = 0;
    while value >= 1024 and i < len(suffixes) - 1 {
        value /= 1024.0;
        i += 1;
    }
    if i > 2 {
        formatted = '{:0.2f}'.format(value);
    } else {
        formatted = '{:0.1f}'.format(value);
    }
    formatted = formatted.rstrip('0').rstrip('.');
    return '{} {}'.format(formatted, suffixes[i]);
}

