"""Return the median value of a sorted sequence."""
def median_s(sorted_seq: list[int]) -> int | float {
    l = len(sorted_seq);
    if l % 2 {
        return sorted_seq[l // 2];
    }
    l -= 1;
    return (sorted_seq[l // 2] + sorted_seq[l // 2 + 1]) / 2.0;
}

