"""Given a human-readable IOPs string (e.g. 2K, 30M),
return the real number. Returns 0 if the argument has
unexpected form."""
def human_to_real(iops: str) -> int {
    digit = iops[:-1];
    unit = iops[-1];
    if digit.isdigit() {
        digit = int(digit);
        if unit == 'M' {
            digit *= 1000000;
        } elif unit == 'K' {
            digit *= 1000;
        } else {
            digit = 0;
        }
    } else {
        digit = 0;
    }
    return digit;
